const { app, BrowserWindow } = require('electron');
const path = require('node:path');
app.setPath('userData', process.argv[2]);
app.enableSandbox();
app.whenReady().then(async () => {
  const w = new BrowserWindow({show:false, webPreferences:{preload:path.join(__dirname,'preload.cjs'),sandbox:true,contextIsolation:true,nodeIntegration:false}});
  await w.loadFile(path.join(__dirname,'index.html'));
  const result = await w.webContents.executeJavaScript("({ preload: window.compatibility, renderer: { require: typeof window.require, process: typeof window.process, Buffer: typeof window.Buffer } })");
  console.log('PROBE '+JSON.stringify({ versions: {electron:process.versions.electron, chrome:process.versions.chrome, node:process.versions.node, v8:process.versions.v8}, platform:process.platform,arch:process.arch,...result }));
  app.quit();
}).catch(error=>{ console.error(error); app.exit(1); });

