const { contextBridge, ipcRenderer } = require('electron');
const modules = {};
for (const name of ['electron', 'electron/renderer', 'electron/common', 'events', 'timers', 'url']) {
  try { require(name); modules[name] = true; } catch { modules[name] = false; }
}
contextBridge.exposeInMainWorld('compatibility', {
  modules,
  globals: { buffer: typeof Buffer, setImmediate: typeof setImmediate, clearImmediate: typeof clearImmediate, process: typeof process, global: typeof global },
  listenerMethods: { on: typeof ipcRenderer.on, once: typeof ipcRenderer.once, off: typeof ipcRenderer.off },
  sandboxed: process.sandboxed,
  contextIsolated: process.contextIsolated,
});
